import React, { useState, useRef, useEffect, useCallback } from "react";
import MemoryPhoto from "./MemoryPhoto";
import PhotoLightbox from "./PhotoLightbox";

/**
 * MemoryGallery:
 * The centerpiece photographic journey upgraded with mobile-first gestures:
 * - Physical touch/drag swipeable card deck (follows finger, springs back or advances)
 * - Double tap for floating hearts
 * - Single tap for intimate story reveal
 * - Long press (>650ms) to focus
 * - Interactive Memory Questions (triggered after browsing photos)
 * - Thin luxury progress bar (MEMORIES 04 / 20)
 * - View mode toggle (Interactive Deck vs Continuous Stream)
 */
export const MemoryGallery = ({
  config,
  memories,
  likedMemories = [],
  onToggleFavorite,
}) => {
  const [activeDeckIndex, setActiveDeckIndex] = useState(0);
  const [viewMode, setViewMode] = useState("deck"); // 'deck' or 'stream'
  const [selectedPhotoIndex, setSelectedPhotoIndex] = useState(null);

  // Drag physics state for swipeable cards
  const [dragX, setDragX] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const startXRef = useRef(0);
  const currentDragRef = useRef(0);

  // Question interaction state
  const [activeQuestion, setActiveQuestion] = useState(null);
  const [questionAnswered, setQuestionAnswered] = useState({}); // { [qIndex]: optionIndex }
  const answeredQuestionsRef = useRef(new Set());

  // Check if a question should trigger for current index
  useEffect(() => {
    if (!config.memoryQuestions) return;

    for (let i = 0; i < config.memoryQuestions.length; i++) {
      const q = config.memoryQuestions[i];
      if (
        activeDeckIndex >= q.triggerAfterIndex &&
        !answeredQuestionsRef.current.has(i)
      ) {
        setActiveQuestion({ ...q, questionIndex: i });
        answeredQuestionsRef.current.add(i);
        break;
      }
    }
  }, [activeDeckIndex, config.memoryQuestions]);

  // Touch & Pointer Drag Listeners
  const handlePointerDown = (e) => {
    // Only drag on card or container, not on nested buttons
    if (e.target.closest("button, .memory-story-overlay")) return;
    setIsDragging(true);
    startXRef.current = e.clientX || (e.touches && e.touches[0].clientX) || 0;
    currentDragRef.current = 0;
    setDragX(0);
  };

  const handlePointerMove = (e) => {
    if (!isDragging) return;
    const clientX = e.clientX || (e.touches && e.touches[0].clientX) || 0;
    const delta = clientX - startXRef.current;
    currentDragRef.current = delta;
    setDragX(delta);
  };

  const handlePointerUp = () => {
    if (!isDragging) return;
    setIsDragging(false);

    const delta = currentDragRef.current;
    const threshold = 75; // px needed to commit a swipe

    if (delta < -threshold && activeDeckIndex < memories.length - 1) {
      // Swiped Left -> Next Card
      setActiveDeckIndex((prev) => prev + 1);
    } else if (delta > threshold && activeDeckIndex > 0) {
      // Swiped Right -> Previous Card
      setActiveDeckIndex((prev) => prev - 1);
    }

    // Spring back
    setDragX(0);
    currentDragRef.current = 0;
  };

  const nextCard = useCallback(() => {
    if (activeDeckIndex < memories.length - 1) {
      setActiveDeckIndex((prev) => prev + 1);
    }
  }, [activeDeckIndex, memories.length]);

  const prevCard = useCallback(() => {
    if (activeDeckIndex > 0) {
      setActiveDeckIndex((prev) => prev - 1);
    }
  }, [activeDeckIndex]);

  // Continuous Stream split (10 per row)
  const half = Math.ceil(memories.length / 2);
  const row1Memories = memories.slice(0, half);
  const row2Memories = memories.slice(half);
  const seamlessRow1 = [...row1Memories, ...row1Memories];
  const seamlessRow2 = [...row2Memories, ...row2Memories];

  const currentMemory = memories[activeDeckIndex];
  const progressPercent = ((activeDeckIndex + 1) / memories.length) * 100;
  const currentNum = String(activeDeckIndex + 1).padStart(2, "0");
  const totalNum = String(memories.length).padStart(2, "0");

  return (
    <section id="memories" className="memories-section" aria-label="Photo Memories Journey">
      {/* Section Header */}
      <div className="memories-header">
        <span className="memories-eyebrow">PHOTO JOURNEY</span>
        <h2 className="memories-title">{config.memoriesHeader.title}</h2>
        <p className="memories-subtitle">{config.memoriesHeader.subtitle}</p>

        {/* View Mode Toggle Button */}
        <div className="gallery-mode-toggle">
          <button
            type="button"
            className={`mode-btn ${viewMode === "deck" ? "active" : ""}`}
            onClick={() => setViewMode("deck")}
            aria-label="Switch to interactive swipe deck mode"
          >
            <span>🃏 Swipe Cards</span>
          </button>
          <button
            type="button"
            className={`mode-btn ${viewMode === "stream" ? "active" : ""}`}
            onClick={() => setViewMode("stream")}
            aria-label="Switch to continuous floating stream mode"
          >
            <span>🌊 Stream Flow</span>
          </button>
        </div>

        {/* Memory Progress Indicator */}
        <div className="memory-progress-wrap" aria-label="Memory progress">
          <div className="progress-label-row">
            <span className="progress-tag">MEMORIES</span>
            <span className="progress-counter">
              {currentNum} <span className="sep">/</span> {totalNum}
            </span>
          </div>
          <div className="progress-track-line">
            <div
              className="progress-fill-line"
              style={{ width: `${progressPercent}%` }}
            />
            <div
              className="progress-dot-handle"
              style={{ left: `${progressPercent}%` }}
            />
          </div>
          <span className="memories-hint">
            {viewMode === "deck"
              ? "Swipe card left/right • Double tap for ❤️ • Tap for story"
              : "Click any photograph to view in full • Hover to pause"}
          </span>
        </div>
      </div>

      {/* VIEW 1: INTERACTIVE SWIPEABLE CARD DECK (Mobile-First) */}
      {viewMode === "deck" ? (
        <div className="deck-container">
          <div
            className="deck-stage"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerCancel={handlePointerUp}
          >
            {/* Background Peeking Card (Next memory preview) */}
            {activeDeckIndex < memories.length - 1 && (
              <div className="deck-peek-card" aria-hidden="true">
                <img
                  src={memories[activeDeckIndex + 1].image}
                  alt=""
                  className="peek-img"
                />
              </div>
            )}

            {/* Current Active Interactive Card */}
            <div
              className={`deck-active-card ${isDragging ? "is-dragging" : "is-springing"}`}
              style={{
                transform: `translate3d(${dragX}px, 0, 0) rotate(${dragX * 0.05}deg)`,
              }}
            >
              <MemoryPhoto
                memory={currentMemory}
                index={activeDeckIndex}
                isFavorite={likedMemories.includes(currentMemory.id)}
                onToggleFavorite={onToggleFavorite}
                onOpenLightbox={() => setSelectedPhotoIndex(activeDeckIndex)}
                isMobileDeck={true}
              />
            </div>
          </div>

          {/* Thumb-friendly Deck Navigation Controls */}
          <div className="deck-controls">
            <button
              type="button"
              className="deck-nav-btn btn-prev"
              onClick={prevCard}
              disabled={activeDeckIndex === 0}
              aria-label="Previous memory card"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polyline points="15 18 9 12 15 6" />
              </svg>
              <span>Prev</span>
            </button>

            <span className="deck-fav-counter">
              {likedMemories.includes(currentMemory.id) ? "❤️ Loved" : "♡ Double tap to love"}
            </span>

            <button
              type="button"
              className="deck-nav-btn btn-next"
              onClick={nextCard}
              disabled={activeDeckIndex === memories.length - 1}
              aria-label="Next memory card"
            >
              <span>Next</span>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polyline points="9 18 15 12 9 6" />
              </svg>
            </button>
          </div>
        </div>
      ) : (
        /* VIEW 2: CONTINUOUS FLOATING STREAMS */
        <div className="stream-viewport">
          <div className="stream-row stream-row-1" aria-label="Memories row 1">
            <div className="stream-track stream-track-ltr">
              {seamlessRow1.map((mem, index) => (
                <MemoryPhoto
                  key={`r1-${mem.id}-${index}`}
                  memory={mem}
                  index={index}
                  isFavorite={likedMemories.includes(mem.id)}
                  onToggleFavorite={onToggleFavorite}
                  onOpenLightbox={() => setSelectedPhotoIndex(memories.findIndex((m) => m.id === mem.id))}
                />
              ))}
            </div>
          </div>

          <div className="stream-row stream-row-2" aria-label="Memories row 2">
            <div className="stream-track stream-track-rtl">
              {seamlessRow2.map((mem, index) => (
                <MemoryPhoto
                  key={`r2-${mem.id}-${index}`}
                  memory={mem}
                  index={index}
                  isFavorite={likedMemories.includes(mem.id)}
                  onToggleFavorite={onToggleFavorite}
                  onOpenLightbox={() => setSelectedPhotoIndex(memories.findIndex((m) => m.id === mem.id))}
                />
              ))}
            </div>
          </div>
        </div>
      )}

      {/* RANDOM "MEMORY QUESTION" MODAL DIALOG */}
      {activeQuestion && (
        <div className="question-modal-backdrop" role="dialog" aria-modal="true">
          <div className="question-card">
            <span className="question-eyebrow">MEMORY MOMENT</span>
            <h3 className="question-text">{activeQuestion.question}</h3>

            <div className="question-options">
              {activeQuestion.options.map((opt, optIdx) => (
                <button
                  key={optIdx}
                  type="button"
                  className={`question-opt-btn ${
                    questionAnswered[activeQuestion.questionIndex] === optIdx ? "selected" : ""
                  }`}
                  onClick={() =>
                    setQuestionAnswered((prev) => ({
                      ...prev,
                      [activeQuestion.questionIndex]: optIdx,
                    }))
                  }
                >
                  {opt.label}
                </button>
              ))}
            </div>

            {/* Playful Romantic Reply */}
            {questionAnswered[activeQuestion.questionIndex] !== undefined && (
              <div className="question-reply-box">
                <p className="question-reply-text">
                  {activeQuestion.options[questionAnswered[activeQuestion.questionIndex]].reply}
                </p>
                <button
                  type="button"
                  className="question-continue-btn"
                  onClick={() => setActiveQuestion(null)}
                >
                  Continue Journey ✨
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Full-Screen Lightbox Modal */}
      {selectedPhotoIndex !== null && (
        <PhotoLightbox
          memory={memories[selectedPhotoIndex]}
          currentIndex={selectedPhotoIndex}
          totalCount={memories.length}
          onClose={() => setSelectedPhotoIndex(null)}
          onPrev={() =>
            setSelectedPhotoIndex((prev) => (prev - 1 + memories.length) % memories.length)
          }
          onNext={() =>
            setSelectedPhotoIndex((prev) => (prev + 1) % memories.length)
          }
        />
      )}
    </section>
  );
};

export default MemoryGallery;
